model = solver.get_model()

# extract edges
edges = []
for i in range(n):
    for j in range(i+1, n):
        v = edge_var(i,j)
        if v in model:
            edges.append((i,j))
        elif -v in model:
            pass
        else:
            # not assigned? check
            pass

print("Edges:", edges)
print("Number of edges:", len(edges))

# verify degrees
degrees = [0]*n
for u,v in edges:
    degrees[u] += 1
    degrees[v] += 1
print("Degrees:", degrees)
print("Min degree:", min(degrees))

# verify fixed edges
for u,v in fixed:
    assert (u,v) in edges, f"Missing fixed edge ({u},{v})"
print("Fixed edges present.")

# verify clique size <= 5
max_clique_found = 0
for k in range(2, 7):
    found = False
    for subset in combinations(range(n), k):
        is_clique = True
        for u,v in combinations(subset, 2):
            if (u,v) not in edges:
                is_clique = False
                break
        if is_clique:
            found = True
            max_clique_found = k
    if not found:
        break
print("Max clique size:", max_clique_found)

# verify coloring
# extract colors
colors = {}
for v in range(n):
    for c in range(max_color):
        if color_var(v,c) in model:
            colors[v] = c
            break
print("Colors:", colors)

# check proper coloring
for u,v in edges:
    assert colors[u] != colors[v], f"Adjacent vertices {u},{v} have same color"
print("Proper coloring verified.")

# check number of colors used
num_colors = len(set(colors.values()))
print("Number of colors used:", num_colors)
